// ───────────────────────────── inventory sheet (v18.2, 22 Oct 2026) ─────────────────────────────
// One Excel-like list per store: last inventory (stock right after the item's last count), sold since, adjusted since
// (stock in, transfers, stock out, corrections), system stock now, the physical count typed in, difference and remarks.
// Saving books only the difference (counted − system stock shown on the sheet), so sales made while counting are kept,
// and keeps every counted line with its remark in the "Inventory Counts" tab.
const IC_TAB = 'Inventory Counts', IC_H = ['Count ref', 'Count date', 'Location', 'SKU', 'Product', 'Unit', 'Last inventory', 'Last inventory date',
  'Sold since', 'Adjusted since', 'System stock', 'Physical count', 'Difference', 'Value of difference ₹', 'Remarks', 'Counted by', 'Saved at'];
const COUNT_MV = { 'Stock count': 1, 'Opening stock': 1 };

const per = {};
allMoves_().filter(m => m.loc === loc && m.sku).sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : (a.saved < b.saved ? -1 : a.saved > b.saved ? 1 : 0)).forEach(m => {
  const o = per[m.sku] = per[m.sku] || { bal: 0, last: 0, lastDate: '', sold: 0, adj: 0 };
  o.bal += m.qty;
  if (COUNT_MV[m.mv]) { o.last = o.bal; o.lastDate = m.date; o.sold = 0; o.adj = 0; }
  else if (/^Sale/i.test(m.mv)) o.sold -= m.qty;
  else o.adj += m.qty;
});
const out = [], showCost = can_(user, 'costs');

const o = per[sku] || { bal: 0, last: 0, lastDate: '', sold: 0, adj: 0 };
if (s_(r[PC.status]) === 'Discontinued' && Math.abs(o.bal) < 0.0005) return;
out.push({ sku: sku, name: s_(r[PC.name]), unit: s_(r[PC.unit]) || 'kg', cat: s_(r[PC.cat]), gtin: s_(r[PC.gtin]), sys: round3_(o.bal),
  last: round3_(o.last), lastDate: o.lastDate, sold: round3_(o.sold), adj: round3_(o.adj), cost: showCost ? (n_(r[PC.cost]) || n_(r[PC.avg])) : 0 });

const diff = round3_(counted - n_(l.sys)), remark = txt_(l.remark, 200), cost = n_(r[PC.cost]) || n_(r[PC.avg]);
rec.push([ref, date, loc, s_(r[PC.sku]), s_(r[PC.name]), s_(r[PC.unit]), round3_(n_(l.last)), s_(l.lastDate), round3_(n_(l.sold)), round3_(n_(l.adj)),
  round3_(n_(l.sys)), counted, diff, cost ? round2_(cost * diff) : '', remark, by, now]);

if (!rec.length) throw new Error('Nothing counted.');
const lock = LockService.getScriptLock(); lock.waitLock(20000);
try {
  const sh = xtab_(IC_TAB, IC_H);
  sh.getRange(sh.getLastRow() + 1, 1, rec.length, IC_H.length).setValues(rec);
  if (rows.length) postLedger_(rows, 'Stock count');
} finally { lock.releaseLock(); }
return { ok: true, ref: ref, counted: rec.length, changed: rows.length, plus: round3_(rows.filter(x => x[6] > 0).reduce((a, x) => a + x[6], 0)),

/** Past inventory counts of a store (latest first), with their lines. */
function countHistory_(d, user) {
  const loc = s_(d && d.location);
  if (!inScope_(stockScope_(user), loc)) throw new Error('You can only see your own store.');
  const g = {};
  xrows_(IC_TAB, IC_H).filter(r => s_(r[2]) === loc).forEach(r => {
    const k = s_(r[0]), o = g[k] = g[k] || { ref: k, date: ymd_(r[1]), by: s_(r[15]), at: iso_(r[16]), lines: [] };
    o.lines.push({ name: s_(r[4]), unit: s_(r[5]), last: n_(r[6]), sold: n_(r[8]), adj: n_(r[9]), sys: n_(r[10]), counted: n_(r[11]), diff: n_(r[12]), remark: s_(r[14]) });
  });
  return Object.keys(g).map(k => g[k]).sort((a, b) => a.at < b.at ? 1 : -1).slice(0, 30);
}

