  '<td class="n"><input class="i num cn_in" data-sku="' + esc(it.sku) + '" data-i="' + i + '" inputmode="decimal" enterkeyhint="next" style="width:84px;min-height:34px;padding:4px 6px;text-align:right" value="' + esc(v === undefined ? '' : v) + '"></td>' +
  '<td class="n cn_d" style="font-weight:600;color:' + (d === null || Math.abs(d) < 0.0005 ? 'var(--mute)' : d < 0 ? 'var(--bad)' : 'var(--ok)') + '">' + (d === null ? '' : Math.abs(d) < 0.0005 ? '✓' : (d > 0 ? '+' : '') + qfmt(d)) + '</td>' +
