      c.lines.map(l => '<tr><td>' + esc(l.name.replace(/^Nutvique\s+/, '')) + '</td><td class="n">' + qfmt(l.last) + '</td><td class="n">' + qfmt(l.sold) + '</td><td class="n">' + qfmt(l.adj) + '</td><td class="n">' + qfmt(l.sys) + '</td><td class="n">' + qfmt(l.counted) + '</td><td class="n" style="color:' + (l.diff < 0 ? 'var(--bad)' : l.diff > 0 ? 'var(--ok)' : '') + '">' + (Math.abs(l.diff) < 0.0005 ? '✓' : (l.diff > 0 ? '+' : '') + qfmt(l.diff)) + '</td><td>' + esc(l.remark) + '</td></tr>').join('') + '</table></div></details>'; }).join('') : '<div class="empty">No counts saved with the inventory sheet yet.</div>', { wide: true }); };
